"""Pydantic schemas for the Part 2 AI Attacker Application.

All schemas strictly forbid extra fields and define the data structures
for observations, attack proposals, and gateway feedback.
"""

from typing import List, Literal, Optional
from pydantic import BaseModel, ConfigDict, Field

AttackType = Literal[
    "capacity_manipulation",
    "inventory_manipulation",
    "sensor_spoofing",
    "replay_attack",
    "coordinated_weak",
    "multi_source",
]


class AttackProposal(BaseModel):
    """Adversarial attack proposal generated by an AI or deterministic planner."""

    model_config = ConfigDict(extra="forbid")

    attack_type: AttackType = Field(
        ...,
        description="One of the 6 whitelisted attack scenario types.",
    )
    target: str = Field(
        ...,
        description="Specific target metric or subsystem matching the attack type.",
    )
    value: Optional[float] = Field(
        None,
        description="Magnitude or target parameter for the attack.",
    )
    objective: str = Field(
        ...,
        min_length=1,
        max_length=500,
        description="Strategic goal or rationale behind the proposed attack.",
    )


class AttackerObservation(BaseModel):
    """Restricted operational observation received from the Attack Gateway."""

    model_config = ConfigDict(extra="forbid")

    target: str
    inventory: float
    free_capacity: float
    temperature: float
    humidity: float
    occupancy: float


class AttackFeedback(BaseModel):
    """Restricted outcome feedback returned by the Attack Gateway."""

    model_config = ConfigDict(extra="forbid")

    attack_id: str
    execution: str
    detection: str
    classification: Optional[str] = None
    timestamp: str


class ProposalGenerationRequest(BaseModel):
    """Request payload to generate an attack proposal."""

    model_config = ConfigDict(extra="forbid")

    planner: Literal["deterministic", "llm"] = "deterministic"
    objective_hint: Optional[str] = None


class ProposalValidationResult(BaseModel):
    """Validation report for an attack proposal."""

    model_config = ConfigDict(extra="forbid")

    valid: bool
    errors: List[str] = Field(default_factory=list)


class LLMPlanResponse(BaseModel):
    """Raw structured plan output parsed from an LLM response."""

    model_config = ConfigDict(extra="forbid")

    strategy_rationale: str = Field(
        ...,
        min_length=1,
        max_length=1000,
        description="Reasoning or tactical explanation behind the proposed maneuver.",
    )
    attack_type: AttackType = Field(
        ...,
        description="One of the 6 whitelisted attack scenario types.",
    )
    target: str = Field(
        ...,
        description="Target metric or subsystem.",
    )
    value: Optional[float] = Field(
        None,
        description="Attack magnitude or parameter.",
    )
    objective: str = Field(
        ...,
        min_length=1,
        max_length=500,
        description="Attack objective string.",
    )


class ProposalGenerationResponse(BaseModel):
    """Response returned when an attack proposal is generated."""

    model_config = ConfigDict(extra="forbid")

    proposal_id: str
    proposal: AttackProposal
    validation: ProposalValidationResult
    planner_label: str
    strategy_rationale: Optional[str] = None
    observed_telemetry_snapshot: Optional[AttackerObservation] = None
    message: str


class AttackerHistoryItem(BaseModel):
    """Historical record of an attack proposal and its execution outcome."""

    model_config = ConfigDict(extra="forbid")

    proposal_id: str
    proposal: AttackProposal
    planner: str
    validation: ProposalValidationResult
    strategy_rationale: Optional[str] = None
    observed_telemetry_snapshot: Optional[AttackerObservation] = None
    executed: bool = False
    result: Optional[AttackFeedback] = None
    timestamp: str


class ExperimentRecord(BaseModel):
    """Immutable evaluation record generated for an executed adversarial experiment."""

    model_config = ConfigDict(extra="forbid")

    experiment_id: str
    attack_id: str
    timestamp: str
    attack_type: str
    target: str
    value: Optional[float] = None
    execution_status: str
    detection_status: str
    classification: Optional[str] = None
    detection_delay_ms: Optional[float] = None


class ExecuteAttackRequest(BaseModel):
    """Explicit human approval payload for executing a pending proposal."""

    proposal_id: Optional[str] = Field(
        None,
        description="ID of the pending proposal being explicitly approved (verified against active proposal).",
    )
    approved: bool = Field(
        True,
        description="Explicit human approval confirmation.",
    )

    model_config = ConfigDict(extra="forbid")


class AttackerResetRequest(BaseModel):
    """Granular reset request payload."""

    scope: Literal["all", "attacker_only", "defender_only", "history_only"] = "all"

    model_config = ConfigDict(extra="forbid")


class TokenLoginRequest(BaseModel):
    """Payload for establishing attacker browser session."""

    token: str = Field(..., min_length=1, max_length=256, description="Attacker access token")

    model_config = ConfigDict(extra="forbid")


